static int file_path(wchar_t *out,J *f){const char *id=str(f,"id");if(!*id||strlen(id)>80||strspn(id,"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-")!=strlen(id))return 0;wchar_t name[100],*w=wide(id);swprintf(name,100,L"%s.bin",w);free(w);join(out,workImages,name);return 1;}
static int file_read(J *f,BYTE **bytes,DWORD *size){wchar_t *path=calloc(32768,sizeof(wchar_t));int ok=file_path(path,f)&&d408_file_read(path,bytes,size,10*1024*1024);free(path);char hash[65];if(ok){d408_hash(*bytes,*size,hash);ok=!strcmp(hash,str(f,"sha256"))&&*size==(DWORD)num(f,"size");}if(!ok){free(*bytes);*bytes=0;}return ok;}
static void attach_file(void){const char *kind;J *old=selected_record(&kind);if(!old)return;wchar_t *path=calloc(32768,sizeof(wchar_t));OPENFILENAMEW of={sizeof(of)};of.hwndOwner=workWindow;of.lpstrFile=path;of.nMaxFile=32768;of.lpstrFilter=L"工作附件\0*.*\0\0";of.Flags=OFN_FILEMUSTEXIST|OFN_NOCHANGEDIR;if(!GetOpenFileNameW(&of)){free(path);return;}BYTE *bytes=0;DWORD size=0;if(!d408_file_read(path,&bytes,&size,10*1024*1024)){free(path);d408_error(workWindow,"附件读取失败或超过10MiB，原数据保留。");return;}J *r=dup(old),*f=cJSON_CreateObject();char id[80],hash[65];uuid(id);d408_hash(bytes,size,hash);ss(f,"id",id);ss(f,"sha256",hash);sn(f,"size",size);const wchar_t *base=wcsrchr(path,L'\\');char *name=utf8(base?base+1:path);ss(f,"name",name);free(name);int ok=file_path(path,f)&&d408_file_write(path,bytes,size);free(path);free(bytes);if(ok){cJSON_AddItemToArray(get(r,"attachments"),f);ok=save_record(kind,r,"add-file");}else cJSON_Delete(f);cJSON_Delete(r);if(!ok)d408_error(workWindow,"附件保存失败，可重试，原记录保持不变。");work_refresh();}
